<?php require __DIR__.'/includes/auth.php';$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();$id=(int)$_POST['id'];$slug=admin_slug($_POST['slug']?:$_POST['title']);if($id)$p->prepare('UPDATE pages SET title=?,slug=?,content=?,status=? WHERE id=?')->execute([$_POST['title'],$slug,$_POST['content'],(int)$_POST['status'],$id]);else$p->prepare('INSERT INTO pages(title,slug,content,status) VALUES(?,?,?,?)')->execute([$_POST['title'],$slug,$_POST['content'],(int)$_POST['status']]);header('Location: pages.php');exit;}$edit=null;if(isset($_GET['id'])){$q=$p->prepare('SELECT * FROM pages WHERE id=?');$q->execute([(int)$_GET['id']]);$edit=$q->fetch();}$rows=$p->query('SELECT * FROM pages ORDER BY id DESC')->fetchAll();$page_title='Pages';require __DIR__.'/includes/header.php';?><div class="form"><form method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="id" value="<?=admin_e($edit['id']??0)?>"><div class="formgrid"><div class="field"><label>Title</label><input required name="title" value="<?=admin_e($edit['title']??'')?>"></div><div class="field"><label>Slug</label><input name="slug" value="<?=admin_e($edit['slug']??'')?>"></div><div class="field full"><label>Content</label><textarea name="content" style="min-height:220px"><?=admin_e($edit['content']??'')?></textarea></div><div class="field"><label>Status</label><select name="status"><option value="1">Published</option><option value="0" <?=isset($edit)&&!$edit['status']?'selected':''?>>Hidden</option></select></div></div><div class="actions"><button class="btn">Save Page</button></div></form></div><div class="section tablebox"><table class="table"><tr><th>Title</th><th>Slug</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=admin_e($r['title'])?></td><td><?=admin_e($r['slug'])?></td><td><?=$r['status']?'Published':'Hidden'?></td><td><a class="btn gray" href="?id=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';?>